#!/usr/bin/env bash
# test-cf-account-migration-bootstrap.sh — the #12931 Doppler bootstrap (bootstrap.sh in the #12931 spec
# directory, generated by soleur:operator-bootstrap), CTO ruling D11.
#
# PROPERTIES
#   P1 the whole stage sequence, driven the way an agent drives it (plan, then the REAL approval
#      hook mints a receipt for the exact apply command, then that command runs), moves a
#      synthesized pre-flip world to the post-swap world, and every write stage is then satisfied
#      (operations=0);
#   P2 branch-copies-tokens refuses (PRECONDITION_FAILED need=swap-0b, zero writes) while any
#      CF_API_TOKEN_PURGE_NEXT / CF_API_TOKEN_DNS_EDIT_NEXT exists — before swap-0b, and after it
#      when a fresh token is staged again;
#   P3 a swap copy that does not read back equal stops the stage at once: no later key is written,
#      no delete runs, every <KEY>_NEXT survives; after the rollback of that key the re-run swaps;
#   P3b a key whose copy read back equal but then moved (a concurrent writer) keeps <KEY>_NEXT (the
#      digest compare sits ABOVE the delete);
#   P4 a failed scope probe stops a swap before its first write;
#   P5 every plan makes no mutating Doppler call; an apply with no receipt exits 75 and writes
#      nothing; no synthesized secret value ever reaches stdout or stderr.
#   P6 a revert copy is accepted by its VALUE, never its name: a _PREV whose write did not read back
#      equal satisfies neither prev-0a nor swap-0a (the neutral "copy neither way" refusal);
#   P6m the mirror: a garbage <KEY> with a good _PREV gets the same neutral refusal from both stages;
#   P7 an EMPTY revert copy satisfies neither prev-0a nor swap-0a;
#   P8 branch-copies-zone-id replaces only the legacy zone id; a third value refuses;
#   P9 the doppler stand-in models the real CLI (`get --plain` prints the value plus ONE newline,
#      `set` stores stdin exactly): every live key and revert copy is byte-exact (cmp against the
#      stored file) and the staged tokens read active.
#   P10 a staged token carrying a quote or an embedded newline is MALFORMED: no curl call, no write.
#   P11 verify accepts a revoked _PREV only when the live key verifies active AND reads the new zone;
#   P11b a key holding the old token (active) with no _PREV and no _NEXT fails verify;
#   P11c 0b keys never swapped, their _NEXT gone and no _PREV, fail verify each;
#   P12 branch-copies-tokens replaces only the old token; prev-0a matches each id key to its OWN
#      legacy id; an id-key _PREV that is not the legacy id does not satisfy prev-0a;
#   P13 an id stored as `hex\n` is refused by id_of (no `$(...)` newline strip);
#   P14 branch-copies-tokens after the revoke recipe deleted a 0b _PREV names the revoke, not prev-0b.
#
# ASSEMBLY. A fixture git repository per world holds a copy of bootstrap.sh at its real relative
# path, a synthesized doppler-config-inventory.txt, and a stub cf-token-scope.sh (the script runs
# only TRACKED files, so the stub is committed). PATH-stubbed `doppler` keeps state in files and
# logs every call; PATH-stubbed `curl` answers /user/tokens/verify and GET /zones/<new zone> (a
# SYNTH-NEW* value reads the new zone, any other value gets 403). Nothing reaches a network.
# Fixtures are synthesized (cq-test-fixtures-synthesized-only): the ids are the public account and
# zone ids from the runbook's id table, the token values are sentinel strings.
#
# MUTATIONS (each proven to land: cmp differs, bash -n clean), each must turn its row RED:
#   M0 plain_get's trailing-newline strip dropped (the pre-fix reads) -> P9, P7 rows
#   M1 the _NEXT delete moved ABOVE the digest compare          -> P3b row
#   M2 the branch-copies-tokens _NEXT refusal dropped            -> P2b row
#   M3 the scope probe call dropped from the swap apply          -> P4 row
#   M4 an existing _PREV accepted by name (prev_copy_sound skipped) -> P6, P7 rows
#   M5 swap overwrites a key that no longer holds its revert copy -> P6 row
#   M6 swap tolerates an unreadable _PREV                        -> P7 row
#   M7 branch-copies-zone-id overwrites any zone id              -> P8 row
#   M8 the stop-after-a-failed-copy return dropped               -> P3 row
#   M9 the shared token character check dropped                  -> P10 rows
#   M10 verify's active check on a revoked _PREV dropped          -> P11 negative row
#   M11 branch-copies-tokens' old-token-only refusal dropped      -> P12a row
#   M12 prev-0a accepts either legacy id for either id key        -> P12b row
#   M13 prev_copy_sound's id-key value check dropped              -> P12c row
#   M14 verify's new-zone read on a revoked _PREV dropped         -> P11b, P11c rows
#   M15 id_of back on a `$(...)` capture of the raw CLI output    -> P13 row
#   M16 the copy loop runs on after a failed copy (no break)     -> P3 row
# NOT MUTATED: P14 pins refusal wording only (the refusal itself predates it and is P2-adjacent).
#
# LOCATION: this suite lives in tests/scripts (not beside the script) and finds bootstrap.sh by glob, so an
# archive-kb move of the spec directory breaks nothing; exactly one match is required, else exit 2.
set -uo pipefail

export TMPDIR="${TMPDIR:-/var/tmp}"
export LC_ALL=C

SUITE_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(git -C "$SUITE_DIR" rev-parse --show-toplevel 2>/dev/null)" || { printf 'HARNESS: not in a git work tree\n' >&2; exit 2; }
mapfile -t _found < <(git -C "$REPO_ROOT" ls-files --cached --others --exclude-standard --full-name \
  '*feat-one-shot-12931-cf-account-migration/bootstrap.sh')
[[ "${#_found[@]}" -eq 1 ]] || { printf 'HARNESS: expected exactly one #12931 bootstrap.sh, found %s\n' "${#_found[@]}" >&2; exit 2; }
SCRIPT_SRC="${REPO_ROOT}/${_found[0]}"
LIB="${REPO_ROOT}/plugins/soleur/scripts/lib/operator-script.sh"
HOOK="${REPO_ROOT}/plugins/soleur/hooks/operator-stage-approval.sh"
REL="${_found[0]}"  # the glob result, so this suite survives archive-kb moving the directory

assert_fixture_dir() {
  case "${1-}" in
    "") printf 'FATAL: fixture dir is EMPTY; git -C "" would operate on %s\n' "$PWD" >&2; exit 2 ;;
    */../*|*/..) printf 'FATAL: fixture dir %s contains ..; refusing\n' "$1" >&2; exit 2 ;;
    /proc/*|/sys/*|/dev/*) printf 'FATAL: fixture dir %s is a synthetic-fs path; refusing\n' "$1" >&2; exit 2 ;;
    /|//|/.) printf 'FATAL: fixture dir resolves to the filesystem root; refusing\n' >&2; exit 2 ;;
    /*) : ;;
    *)  printf 'FATAL: fixture dir %s is RELATIVE; refusing\n' "$1" >&2; exit 2 ;;
  esac
}

# shellcheck source=../../plugins/soleur/test/lib/git-fixture-env.sh
source "${REPO_ROOT}/plugins/soleur/test/lib/git-fixture-env.sh"

for bin in jq timeout git perl cmp; do command -v "$bin" >/dev/null 2>&1 || { printf 'HARNESS: %s is required\n' "$bin" >&2; exit 2; }; done
[[ -r "$SCRIPT_SRC" && -r "$LIB" && -r "$HOOK" ]] || { printf 'HARNESS: script, library or hook missing\n' >&2; exit 2; }

PASS=0; FAIL=0
pass() { PASS=$((PASS + 1)); echo "  [ok] $1"; }
fail() { FAIL=$((FAIL + 1)); echo "  [FAIL] $1" >&2; }
check() { if [[ "$2" -eq 0 ]]; then pass "$1"; else fail "$1 (last out: $(printf '%s' "${OUT:-}" | tr '\n' ' ' | cut -c1-300))"; fi; }

# Instrument self-test: both helpers must move their counter.
check "instrument self-test (pass arm)" 0 >/dev/null
check "instrument self-test (fail arm)" 1 >/dev/null 2>&1
if [[ "$PASS" -ne 1 || "$FAIL" -ne 1 ]]; then printf 'INSTRUMENT SELF-TEST FAILED (pass=%s fail=%s)\n' "$PASS" "$FAIL" >&2; exit 2; fi
PASS=0; FAIL=0

SB="$(mktemp -d -t cfam-bootstrap.XXXXXXXX)" || { printf 'HARNESS: mktemp failed\n' >&2; exit 2; }
trap 'chmod -R u+rwx "$SB" 2>/dev/null; rm -rf "$SB"' EXIT
ALL_OUT="$SB/all-output.log"; : > "$ALL_OUT"

readonly NZ=951ce525552201ec6c696b24251abed7 NA=66d4f93f7397f196544e9fe84c3557c2
readonly OZ=5af02a2f394e9ba6e0ea23c381a26b67 OA=4d5ba6f096b2686fbdd404167dd4e125
readonly K0A=(CF_API_TOKEN CF_API_TOKEN_RULESETS CF_API_TOKEN_PAGES)
readonly K0B=(CF_API_TOKEN_ZONE_SETTINGS CF_API_TOKEN_BOT_MANAGEMENT CF_API_TOKEN_DNS_EDIT CF_API_TOKEN_PURGE)
old_val() { printf 'SYNTH-OLD-%s-SENTINEL' "$1"; }
new_val() { printf 'SYNTH-NEW-%s-SENTINEL' "$1"; }

# --- stubs ----------------------------------------------------------------------
write_stubs() { # <bin-dir>
  local b="$1"; assert_fixture_dir "$b"; mkdir -p "$b"
  cat > "$b/doppler" <<'DOPPLER'
#!/usr/bin/env bash
# State: $STUB_D/<config>/<NAME> holds a value byte-exact. Models the real CLI: `get --plain` prints
# the value plus ONE trailing newline (measured on a non-secret key: `soleur\n`; an empty value is a
# bare `\n`); `set` stores stdin exactly. Flags:
#   $STUB_D/.unreadable/<config>       the names listing of <config> fails
#   $STUB_D/.corrupt/<config>.<NAME>   a set of that name stores a DIFFERENT value
#   $STUB_D/.clobber-on-set/<config>.<NAME>  holds OTHER: a set of NAME also overwrites OTHER
#                                      (a concurrent writer, after OTHER's own copy read back equal)
log() { printf '%s\t%s\n' "$1" "$2" >> "$STUB_LOG"; }
args=("$@"); proj=""; cfg=""; i=0
while (( i < ${#args[@]} )); do
  case "${args[i]}" in -p) proj="${args[i+1]:-}"; i=$((i+2)) ;; -c) cfg="${args[i+1]:-}"; i=$((i+2)) ;; *) i=$((i+1)) ;; esac
done
[[ "$proj" == "soleur" && -n "$cfg" ]] || { log mutating "BADARGS $*"; exit 64; }
D="$STUB_D/$cfg"
case "$1 ${2:-}" in
  "secrets --only-names")
    log read "list $cfg"
    [[ "${3:-}" == "--json" ]] || exit 64
    [[ -e "$STUB_D/.unreadable/$cfg" || ! -d "$D" ]] && exit 1
    ls -1 "$D" | jq -R -s -c 'split("\n") | map(select(length > 0)) | map({(.): {}}) | add // {}'
    exit 0 ;;
  "secrets get")
    log read "get $cfg/$3"
    [[ " $* " == *" --plain "* ]] || exit 64
    [[ -f "$D/$3" ]] || exit 1
    cat "$D/$3"; printf '\n'; exit 0 ;;
  "secrets set")
    log mutating "set $cfg/$3"
    [[ " $* " == *" --silent "* ]] || exit 64
    mkdir -p "$D"
    if [[ -e "$STUB_D/.corrupt/$cfg.$3" ]]; then { cat; printf 'CORRUPTED'; } > "$D/$3"; else cat > "$D/$3"; fi
    if [[ -f "$STUB_D/.clobber-on-set/$cfg.$3" ]]; then printf 'SYNTH-CLOBBERED' > "$D/$(cat "$STUB_D/.clobber-on-set/$cfg.$3")"; fi
    exit 0 ;;
  "secrets delete")
    log mutating "delete $cfg/$3"
    [[ " $* " == *" --yes "* ]] || exit 64
    rm -f "$D/$3"; exit 0 ;;
esac
log mutating "UNMODELLED $*"
exit 64
DOPPLER
  cat > "$b/curl" <<'CURL'
#!/usr/bin/env bash
# Two endpoints. The WHOLE config must be the one header line: a second line (an injected URL) fails
# both. Token naming decides the account: SYNTH-NEW-* / SYNTH-NEW2-* are new-account tokens, every
# other SYNTH-* value (SYNTH-OLD-*, SYNTH-THIRD-*, ...) is old-account.
#   /user/tokens/verify      any well-formed SYNTH-* token is active (an old token is active until it
#                            is revoked); $STUB_D/.curl-inactive makes every token inactive.
#   /zones/<new zone id>     a new-account token answers 200 with that zone; an old one answers 403
#                            with success:false.
# Each endpoint has its own switch so verify's two checks are killed independently; a real revoked
# token fails both.
url=""; for a in "$@"; do case "$a" in https://*) url="$a" ;; esac; done
printf 'read\tcurl %s\n' "$url" >> "$STUB_LOG"
cfg="$(cat)"
case "$url" in
  https://api.cloudflare.com/client/v4/user/tokens/verify)
    re='^header = "Authorization: Bearer SYNTH-[A-Z0-9_-]+"$'
    if [[ ! -e "$STUB_D/.curl-inactive" && "$cfg" =~ $re ]]; then
      printf '{"success":true,"result":{"id":"x","status":"active"}}'
    else
      printf '{"success":false,"errors":[{"code":1000}]}'
    fi ;;
  https://api.cloudflare.com/client/v4/zones/951ce525552201ec6c696b24251abed7)
    re='^header = "Authorization: Bearer SYNTH-NEW[0-9]*-[A-Z0-9_-]+"$'
    if [[ "$cfg" =~ $re ]]; then
      printf '{"success":true,"result":{"id":"951ce525552201ec6c696b24251abed7","name":"synth.invalid"}}'
    else
      printf '{"success":false,"errors":[{"code":9109,"message":"Unauthorized to access requested resource"}]}'
    fi ;;
  *) exit 64 ;;
esac
CURL
  chmod +x "$b/doppler" "$b/curl"
}

# make_repo <dir> <bootstrap-src> — a fixture repository tracking the script, the inventory and a
# stub cf-token-scope.sh.
make_repo() {
  local r="$1" src="$2"; assert_fixture_dir "$r"
  mkdir -p "$r/$(dirname "$REL")" "$r/apps/web-platform/infra" "$r/plugins/soleur/skills/cf-token-scope/scripts"
  cp "$src" "$r/$REL"
  printf '# synthesized inventory\nprd_terraform\nprd\nprd_cla\ndev\nprd_other\n' > "$r/apps/web-platform/infra/doppler-config-inventory.txt"
  cat > "$r/plugins/soleur/skills/cf-token-scope/scripts/cf-token-scope.sh" <<'SCOPE'
#!/usr/bin/env bash
printf 'read\tscope %s\n' "$*" >> "$STUB_LOG"
prof=""; [[ "${1:-}" == "--profile" ]] && prof="${2:-}"
if [[ -e "$STUB_D/.scope-fail" ]]; then echo "probe=$prof verdict=denied"; exit 3; fi
echo "cf-token-scope: migration profile $prof (stub)"
echo "probe=$prof verdict=pass"
SCOPE
  printf '.env\n.env.tmp.*\nbootstrap-runs.jsonl\n' > "$r/.gitignore"
  (
    git_fixture_env "$r" || exit 1
    cd "$r" && git init -q . && git add -A && git commit -qm fixture ) >/dev/null 2>&1 || { printf 'HARNESS: fixture repo failed\n' >&2; exit 2; }
}

# world <name> [<bootstrap-src>] — fresh state, the pre-flip world, a fixture repo.
world() {
  local src="${2:-$SCRIPT_SRC}" k c
  W="$SB/w-$1"; rm -rf "$W"; mkdir -p "$W/state" "$W/xdg"
  write_stubs "$W/bin"
  make_repo "$W/repo" "$src"
  S="$W/repo/$REL"
  STUB_D="$W/state"; STUB_LOG="$W/calls.log"; : > "$STUB_LOG"
  mkdir -p "$STUB_D/prd_terraform" "$STUB_D/prd" "$STUB_D/prd_cla" "$STUB_D/dev" "$STUB_D/prd_other" "$STUB_D/.corrupt" "$STUB_D/.unreadable" "$STUB_D/.clobber-on-set"
  sv() { printf '%s' "$3" > "$STUB_D/$1/$2"; }
  sv prd_terraform CF_ZONE_ID "$OZ"; sv prd_terraform CF_ACCOUNT_ID "$OA"; sv prd_terraform CF_R2_ACCOUNT_ID "$OA"
  for k in "${K0A[@]}" "${K0B[@]}"; do sv prd_terraform "$k" "$(old_val "$k")"; sv prd_terraform "${k}_NEXT" "$(new_val "$k")"; done
  sv prd CF_ZONE_ID "$OZ"; sv prd CF_API_TOKEN_PURGE "$(old_val CF_API_TOKEN_PURGE)"; sv prd CF_API_TOKEN_DNS_EDIT "$(old_val CF_API_TOKEN_DNS_EDIT)"
  sv prd OTHER_KEY unrelated
  sv prd_cla CF_ZONE_ID "$OZ"; sv prd_cla OTHER_KEY unrelated
  sv dev CF_ZONE_ID "$OZ"; sv dev OTHER_KEY unrelated
  sv prd_other OTHER_KEY unrelated
  CHILD_ENV=("PATH=$W/bin:$PATH" "SOLEUR_OP_LIB=$LIB" "ENV_FILE=$W/xdg/.env" "SOLEUR_BOOTSTRAP_LEDGER=$W/ledger.jsonl"
             "STUB_D=$STUB_D" "STUB_LOG=$STUB_LOG" "XDG_STATE_HOME=$W/xdg")
}
val() { cat "$STUB_D/$1/$2" 2>/dev/null; }
has() { [[ -f "$STUB_D/$1/$2" ]]; }

OUT=""; RC=0
run() {
  OUT="$(env -u CLAUDE_PLUGIN_ROOT -u CLAUDE_CODE_ENTRYPOINT "${CHILD_ENV[@]}" timeout 60 bash "$S" "$@" </dev/null 2>&1)"; RC=$?
  printf '%s\n' "$OUT" >> "$ALL_OUT"
}
digest() { sed -n 's/^SOLEUR_BOOTSTRAP_PLAN stage=[^ ]* operations=[0-9]* digest=\([0-9a-f]*\)$/\1/p' <<<"$OUT"; }
ops() { sed -n 's/^SOLEUR_BOOTSTRAP_PLAN stage=[^ ]* operations=\([0-9]*\) digest=.*$/\1/p' <<<"$OUT"; }
mut() { grep -c "^mutating" "$STUB_LOG" || true; }
# approve <stage>: plan, the REAL hook mints a receipt for the exact apply command, then the
# rewritten command runs as the harness would run it. Leaves OUT/RC of the apply.
approve() {
  local stage="$1" d cmd in newc
  run --stage "$stage"
  d="$(digest)"
  [[ -n "$d" && "$(ops)" -gt 0 ]] || { OUT="approve(): no plan with operations for ${stage}: ${OUT}"; RC=99; return; }
  cmd="bash $S --stage $stage --apply --plan-digest $d"
  in="$(jq -nc --arg c "$cmd" '{tool_name:"Bash",tool_input:{command:$c},permission_mode:"default",session_id:"s",cwd:"/",hook_event_name:"PreToolUse"}')"
  newc="$(printf '%s' "$in" | env "XDG_STATE_HOME=$W/xdg" CLAUDE_CODE_ENTRYPOINT=cli bash "$HOOK" | jq -r '.hookSpecificOutput.updatedInput.command // empty')"
  [[ -n "$newc" ]] || { OUT="approve(): the hook minted nothing for: ${cmd}"; RC=98; return; }
  OUT="$(env -u CLAUDE_PLUGIN_ROOT "${CHILD_ENV[@]}" timeout 60 bash -c "$newc" </dev/null 2>&1)"; RC=$?
  printf '%s\n' "$OUT" >> "$ALL_OUT"
}

# --- rows (each returns 0 when its property holds; callable on a mutant source) ---------
# P3: one key's copy does not read back equal -> the stage stops at once: no LATER key is written
# (CF_API_TOKEN_PAGES, after the failed CF_API_TOKEN_RULESETS, keeps the old token and sees no set)
# and no delete runs, so every _NEXT survives; once that key is rolled back (its _PREV copied over
# it), the re-run swap completes.
row_p3_mismatch_keeps_next() { # <bootstrap-src>
  local k
  world p3 "$1"
  approve prev-0a; [[ "$RC" -eq 0 ]] || return 1
  approve flip-ids; [[ "$RC" -eq 0 ]] || return 1
  : > "$STUB_D/.corrupt/prd_terraform.CF_API_TOKEN_RULESETS"
  : > "$STUB_LOG"
  approve swap-0a
  [[ "$RC" -ne 0 ]] || return 1
  grep -qF 'SOLEUR_CFAM_COPY_MISMATCH src=prd_terraform/CF_API_TOKEN_RULESETS_NEXT dst=prd_terraform/CF_API_TOKEN_RULESETS' <<<"$OUT" || return 1
  for k in "${K0A[@]}"; do
    [[ "$(val prd_terraform "${k}_NEXT")" == "$(new_val "$k")" ]] || return 1
  done
  ! grep -qE '^mutating[[:space:]]delete ' "$STUB_LOG" || return 1
  ! grep -qxF "$(printf 'mutating\tset prd_terraform/CF_API_TOKEN_PAGES')" "$STUB_LOG" || return 1
  [[ "$(val prd_terraform CF_API_TOKEN_PAGES)" == "$(old_val CF_API_TOKEN_PAGES)" ]] || return 1
  # the documented rollback of the failed key, then the re-run
  rm -f "$STUB_D/.corrupt/prd_terraform.CF_API_TOKEN_RULESETS"
  cp "$STUB_D/prd_terraform/CF_API_TOKEN_RULESETS_PREV" "$STUB_D/prd_terraform/CF_API_TOKEN_RULESETS"
  approve swap-0a; [[ "$RC" -eq 0 ]] || return 1
  for k in "${K0A[@]}"; do
    [[ "$(val prd_terraform "$k")" == "$(new_val "$k")" ]] && ! has prd_terraform "${k}_NEXT" || return 1
  done
}
# P3b: a key whose copy read back equal but whose value then moved (a concurrent writer) keeps its
# _NEXT: the digest compare sits ABOVE the delete.
row_p3b_drift_keeps_next() { # <bootstrap-src>
  world p3b "$1"
  approve prev-0a; [[ "$RC" -eq 0 ]] || return 1
  approve flip-ids; [[ "$RC" -eq 0 ]] || return 1
  printf 'CF_API_TOKEN' > "$STUB_D/.clobber-on-set/prd_terraform.CF_API_TOKEN_PAGES"
  approve swap-0a
  [[ "$RC" -ne 0 ]] || return 1
  grep -qF 'SOLEUR_CFAM_SWAP_MISMATCH name=CF_API_TOKEN kept=CF_API_TOKEN_NEXT' <<<"$OUT" || return 1
  [[ "$(val prd_terraform CF_API_TOKEN_NEXT)" == "$(new_val CF_API_TOKEN)" ]]
}
row_p2b_restaged_refuses() { # <bootstrap-src>
  local s
  world p2b "$1"
  for s in prev-0a flip-ids swap-0a branch-copies-zone-id prev-0b swap-0b; do approve "$s"; [[ "$RC" -eq 0 ]] || return 1; done
  printf '%s' "SYNTH-NEW2-CF_API_TOKEN_PURGE-SENTINEL" > "$STUB_D/prd_terraform/CF_API_TOKEN_PURGE_NEXT"
  : > "$STUB_LOG"
  run --stage branch-copies-tokens
  [[ "$RC" -eq 1 && -z "$(digest)" && "$(mut)" -eq 0 ]] && grep -qF 'SOLEUR_BOOTSTRAP_PRECONDITION_FAILED stage=branch-copies-tokens need=swap-0b' <<<"$OUT"
}
row_p4_probe_fail_stops() { # <bootstrap-src>
  world p4 "$1"
  approve prev-0a; [[ "$RC" -eq 0 ]] || return 1
  approve flip-ids; [[ "$RC" -eq 0 ]] || return 1
  : > "$STUB_D/.scope-fail"
  : > "$STUB_LOG"
  approve swap-0a
  [[ "$RC" -ne 0 ]] || return 1
  grep -qE '^read[[:space:]]scope --profile redirects-dns --staged$' "$STUB_LOG" || return 1
  [[ "$(mut)" -eq 0 ]] || return 1
  [[ "$(val prd_terraform CF_API_TOKEN)" == "$(old_val CF_API_TOKEN)" ]] && has prd_terraform CF_API_TOKEN_NEXT
}

# neutral_refusal <KEY> — OUT carries the direction-free "copy neither way" advice and no copy direction.
neutral_refusal() {
  grep -qF "one of ${1} / ${1}_PREV is not the old token; copy neither way. Both an old and a new token verify active, so status cannot tell them apart: the one that does NOT read the new zone (runbook Halt 'a revert copy is not sound') is the old token." <<<"$OUT" \
    && ! grep -qF 'keep the one that verifies active' <<<"$OUT" \
    && ! grep -qF 'back over' <<<"$OUT"
}
# P6: a revert copy is accepted by its VALUE, never by its name (#12932 review DI-1). A prev-0a write
# that does not read back equal leaves CF_API_TOKEN_PREV named but wrong: the re-run must refuse
# rather than call it satisfied, and swap-0a must refuse rather than overwrite the only old copy.
row_p6_bad_revert_copy_refuses() { # <bootstrap-src>
  world p6 "$1"
  : > "$STUB_D/.corrupt/prd_terraform.CF_API_TOKEN_PREV"
  approve prev-0a; [[ "$RC" -ne 0 ]] && grep -qF 'SOLEUR_CFAM_COPY_MISMATCH src=prd_terraform/CF_API_TOKEN dst=prd_terraform/CF_API_TOKEN_PREV' <<<"$OUT" || return 1
  rm -f "$STUB_D/.corrupt/prd_terraform.CF_API_TOKEN_PREV"
  # the two keys after the failed one get sound copies, so swap-0a reaches CF_API_TOKEN's own guard
  printf '%s' "$(old_val CF_API_TOKEN_RULESETS)" > "$STUB_D/prd_terraform/CF_API_TOKEN_RULESETS_PREV"
  printf '%s' "$(old_val CF_API_TOKEN_PAGES)" > "$STUB_D/prd_terraform/CF_API_TOKEN_PAGES_PREV"
  : > "$STUB_LOG"; run --stage prev-0a
  [[ "$RC" -eq 1 && -z "$(digest)" && "$(mut)" -eq 0 ]] && grep -qF 'SOLEUR_BOOTSTRAP_PRECONDITION_FAILED stage=prev-0a need=inventory' <<<"$OUT" \
    && grep -qF 'neither CF_API_TOKEN_PREV nor CF_API_TOKEN_NEXT equals CF_API_TOKEN' <<<"$OUT" && neutral_refusal CF_API_TOKEN || return 1
  approve flip-ids; [[ "$RC" -eq 0 ]] || return 1
  : > "$STUB_LOG"; run --stage swap-0a
  [[ "$RC" -eq 1 && -z "$(digest)" && "$(mut)" -eq 0 ]] && grep -qF 'SOLEUR_BOOTSTRAP_PRECONDITION_FAILED stage=swap-0a need=inventory' <<<"$OUT" \
    && grep -qF 'prd_terraform/CF_API_TOKEN holds neither its revert copy' <<<"$OUT" && neutral_refusal CF_API_TOKEN || return 1
  [[ "$(val prd_terraform CF_API_TOKEN)" == "$(old_val CF_API_TOKEN)" ]] && has prd_terraform CF_API_TOKEN_NEXT
}
# P7: an EMPTY revert copy (a get|set pipe whose get failed) never satisfies prev-0a or swap-0a. The
# swap half is the interrupted-swap state (the key already holds the staged token), so only the
# readable-_PREV guard stands between it and deleting the last staging copy.
row_p7_empty_revert_copy_refuses() { # <bootstrap-src>
  world p7 "$1"
  : > "$STUB_D/prd_terraform/CF_API_TOKEN_PAGES_PREV"
  : > "$STUB_LOG"; run --stage prev-0a
  [[ "$RC" -eq 1 && -z "$(digest)" && "$(mut)" -eq 0 ]] && grep -qF 'SOLEUR_BOOTSTRAP_PRECONDITION_FAILED stage=prev-0a need=inventory' <<<"$OUT" || return 1
  rm -f "$STUB_D/prd_terraform/CF_API_TOKEN_PAGES_PREV"
  approve prev-0a; [[ "$RC" -eq 0 ]] || return 1
  approve flip-ids; [[ "$RC" -eq 0 ]] || return 1
  : > "$STUB_D/prd_terraform/CF_API_TOKEN_PAGES_PREV"
  printf '%s' "$(new_val CF_API_TOKEN_PAGES)" > "$STUB_D/prd_terraform/CF_API_TOKEN_PAGES"
  : > "$STUB_LOG"; run --stage swap-0a
  [[ "$RC" -eq 1 && -z "$(digest)" && "$(mut)" -eq 0 ]] && grep -qF 'SOLEUR_BOOTSTRAP_PRECONDITION_FAILED stage=swap-0a need=prev-0a' <<<"$OUT" \
    && grep -qF 'prd_terraform/CF_API_TOKEN_PAGES_PREV is unreadable or empty' <<<"$OUT" || return 1
  has prd_terraform CF_API_TOKEN_PAGES_NEXT
}
# P8: branch-copies-zone-id replaces only the legacy id; a third value refuses (review DI-2).
row_p8_third_zone_refuses() { # <bootstrap-src>
  world p8 "$1"
  approve prev-0a; [[ "$RC" -eq 0 ]] || return 1
  approve flip-ids; [[ "$RC" -eq 0 ]] || return 1
  printf '%s' 0123456789abcdef0123456789abcdef > "$STUB_D/dev/CF_ZONE_ID"
  : > "$STUB_LOG"; run --stage branch-copies-zone-id
  [[ "$RC" -eq 1 && -z "$(digest)" && "$(mut)" -eq 0 ]] && grep -qF 'SOLEUR_BOOTSTRAP_PRECONDITION_FAILED stage=branch-copies-zone-id need=inventory' <<<"$OUT" || return 1
  [[ "$(val dev CF_ZONE_ID)" == 0123456789abcdef0123456789abcdef ]]
}

# P6m (mirror of P6): the swap's write to <KEY> did not read back equal, so <KEY> is garbage and
# <KEY>_PREV is good. The prev re-run and the swap re-run give the same neutral refusal.
row_p6m_garbage_key_neutral() { # <bootstrap-src>
  world p6m "$1"
  approve prev-0a; [[ "$RC" -eq 0 ]] || return 1
  approve flip-ids; [[ "$RC" -eq 0 ]] || return 1
  : > "$STUB_D/.corrupt/prd_terraform.CF_API_TOKEN"
  approve swap-0a
  [[ "$RC" -ne 0 ]] && grep -qF 'SOLEUR_CFAM_COPY_MISMATCH src=prd_terraform/CF_API_TOKEN_NEXT dst=prd_terraform/CF_API_TOKEN' <<<"$OUT" || return 1
  rm -f "$STUB_D/.corrupt/prd_terraform.CF_API_TOKEN"
  : > "$STUB_LOG"; run --stage prev-0a
  [[ "$RC" -eq 1 && -z "$(digest)" && "$(mut)" -eq 0 ]] && grep -qF 'SOLEUR_BOOTSTRAP_PRECONDITION_FAILED stage=prev-0a need=inventory' <<<"$OUT" \
    && neutral_refusal CF_API_TOKEN || return 1
  : > "$STUB_LOG"; run --stage swap-0a
  [[ "$RC" -eq 1 && -z "$(digest)" && "$(mut)" -eq 0 ]] && neutral_refusal CF_API_TOKEN || return 1
  [[ "$(val prd_terraform CF_API_TOKEN_PREV)" == "$(old_val CF_API_TOKEN)" ]] && has prd_terraform CF_API_TOKEN_NEXT
}
# same_bytes <config> <name> <expected> — the stored file equals <expected> byte for byte. cmp, never
# a `$(...)` compare: a capture strips trailing newlines, so it would call `v\n` equal to `v`.
same_bytes() {
  printf '%s' "$3" > "$W/expect.bin"
  cmp -s -- "$STUB_D/$1/$2" "$W/expect.bin"
}
# P9: under the real-CLI stand-in, copies are byte-exact and the staged tokens read active.
row_p9_cli_newline() { # <bootstrap-src>
  local s k
  world p9 "$1"
  approve prev-0a; [[ "$RC" -eq 0 ]] && same_bytes prd_terraform CF_API_TOKEN_PREV "$(old_val CF_API_TOKEN)" || return 1
  for s in flip-ids swap-0a branch-copies-zone-id prev-0b swap-0b; do approve "$s"; [[ "$RC" -eq 0 ]] || return 1; done
  grep -qxF 'SOLEUR_CFAM_TOKEN_ACTIVE name=CF_API_TOKEN_DNS_EDIT_NEXT' <<<"$OUT" \
    && grep -qxF 'SOLEUR_CFAM_TOKEN_ACTIVE name=CF_API_TOKEN_PURGE_NEXT' <<<"$OUT" || return 1
  for k in "${K0A[@]}" "${K0B[@]}"; do
    same_bytes prd_terraform "$k" "$(new_val "$k")" && same_bytes prd_terraform "${k}_PREV" "$(old_val "$k")" || return 1
  done
}
# P10: a staged token that would splice into curl's config as more than one quoted header is
# MALFORMED: its own marker, no curl call, no write. <how>: quote | newline.
row_p10_malformed_next() { # <bootstrap-src> <how>
  local s
  world "p10-$2" "$1"
  for s in prev-0a flip-ids swap-0a branch-copies-zone-id prev-0b; do approve "$s"; [[ "$RC" -eq 0 ]] || return 1; done
  if [[ "$2" == quote ]]; then printf '%s' 'SYNTH-BAD"QUOTE-SENTINEL' > "$STUB_D/prd_terraform/CF_API_TOKEN_DNS_EDIT_NEXT"
  else printf '%s\n%s' 'SYNTH-BAD-LINE1' 'url = "https://injected.invalid/"' > "$STUB_D/prd_terraform/CF_API_TOKEN_DNS_EDIT_NEXT"; fi
  : > "$STUB_LOG"
  approve swap-0b
  [[ "$RC" -ne 0 ]] || return 1
  grep -qxF 'SOLEUR_CFAM_TOKEN_MALFORMED name=CF_API_TOKEN_DNS_EDIT_NEXT' <<<"$OUT" || return 1
  ! grep -qF 'SOLEUR_CFAM_TOKEN_ACTIVE name=CF_API_TOKEN_DNS_EDIT_NEXT' <<<"$OUT" || return 1
  ! grep -qF 'curl ' "$STUB_LOG" || return 1
  [[ "$(mut)" -eq 0 && "$(val prd_terraform CF_API_TOKEN_DNS_EDIT)" == "$(old_val CF_API_TOKEN_DNS_EDIT)" ]]
}
# full_sequence — every write stage applied, in runbook order; rc 1 on the first that fails.
full_sequence() {
  local s
  for s in prev-0a flip-ids swap-0a branch-copies-zone-id prev-0b swap-0b branch-copies-tokens; do approve "$s"; [[ "$RC" -eq 0 ]] || return 1; done
}
# P11: the runbook revokes the three 0a tokens (deleting their _PREV) before verify runs. Verify is
# then ok on the live keys' own active check; with those keys inactive it fails. <want>: ok | inactive.
row_p11_verify_prev_revoked() { # <bootstrap-src> <want>
  local k
  world "p11-$2" "$1"
  full_sequence || return 1
  for k in "${K0A[@]}"; do rm -f "$STUB_D/prd_terraform/${k}_PREV"; done
  [[ "$2" == inactive ]] && : > "$STUB_D/.curl-inactive"
  run --stage verify
  if [[ "$2" == ok ]]; then
    [[ "$RC" -eq 0 ]] && grep -qx 'SOLEUR_CFAM_VERIFY verdict=ok' <<<"$OUT" || return 1
    for k in "${K0A[@]}"; do grep -qxF "SOLEUR_CFAM_VERIFY check=prd_terraform/${k}=swapped-prev-revoked verdict=ok" <<<"$OUT" || return 1; done
    grep -qxF 'SOLEUR_CFAM_VERIFY check=prd_terraform/CF_API_TOKEN_PURGE=swapped verdict=ok' <<<"$OUT"
  else
    [[ "$RC" -eq 1 ]] && grep -qx 'SOLEUR_CFAM_VERIFY verdict=fail' <<<"$OUT" \
      && grep -qxF 'SOLEUR_CFAM_VERIFY check=prd_terraform/CF_API_TOKEN=swapped-prev-revoked verdict=fail' <<<"$OUT"
  fi
}
# P12a: a branch config whose token is neither prd_terraform's new one nor the old one is refused,
# never overwritten.
row_p12a_branch_third_token_refuses() { # <bootstrap-src>
  local s
  world p12a "$1"
  for s in prev-0a flip-ids swap-0a branch-copies-zone-id prev-0b swap-0b; do approve "$s"; [[ "$RC" -eq 0 ]] || return 1; done
  printf '%s' 'SYNTH-THIRD-PURGE-SENTINEL' > "$STUB_D/prd/CF_API_TOKEN_PURGE"
  : > "$STUB_LOG"; run --stage branch-copies-tokens
  [[ "$RC" -eq 1 && -z "$(digest)" && "$(mut)" -eq 0 ]] && grep -qF 'SOLEUR_BOOTSTRAP_PRECONDITION_FAILED stage=branch-copies-tokens need=inventory' <<<"$OUT" \
    && grep -qF 'soleur/prd CF_API_TOKEN_PURGE holds neither the new token' <<<"$OUT" || return 1
  [[ "$(val prd CF_API_TOKEN_PURGE)" == 'SYNTH-THIRD-PURGE-SENTINEL' ]]
}
# P12b: prev-0a matches each id key to its OWN legacy id: CF_ZONE_ID holding the legacy ACCOUNT id
# is not a zone id to keep.
row_p12b_crossed_legacy_id_refuses() { # <bootstrap-src>
  world p12b "$1"
  printf '%s' "$OA" > "$STUB_D/prd_terraform/CF_ZONE_ID"
  : > "$STUB_LOG"; run --stage prev-0a
  [[ "$RC" -eq 1 && -z "$(digest)" && "$(mut)" -eq 0 ]] && grep -qF 'SOLEUR_BOOTSTRAP_PRECONDITION_FAILED stage=prev-0a need=inventory' <<<"$OUT" \
    && grep -qF 'CF_ZONE_ID in prd_terraform no longer holds the legacy id' <<<"$OUT"
}
# P12c: an existing CF_ZONE_ID_PREV that is not the legacy zone id does not satisfy prev-0a.
row_p12c_bad_id_prev_refuses() { # <bootstrap-src>
  world p12c "$1"
  printf '%s' 0123456789abcdef0123456789abcdef > "$STUB_D/prd_terraform/CF_ZONE_ID_PREV"
  : > "$STUB_LOG"; run --stage prev-0a
  [[ "$RC" -eq 1 && -z "$(digest)" && "$(mut)" -eq 0 ]] && grep -qF 'SOLEUR_BOOTSTRAP_PRECONDITION_FAILED stage=prev-0a need=inventory' <<<"$OUT" \
    && grep -qF 'prd_terraform/CF_ZONE_ID_PREV exists but does not hold the legacy id' <<<"$OUT"
}
# P11b: a key that holds the OLD token with no _PREV and no _NEXT is not swapped, though the old
# token verifies active: it cannot read the new zone. Its sibling keys stay ok (the fail is this key's).
row_p11b_old_token_no_prev_fails() { # <bootstrap-src>
  world p11b "$1"
  full_sequence || return 1
  rm -f "$STUB_D/prd_terraform/CF_API_TOKEN_PREV"
  printf '%s' "$(old_val CF_API_TOKEN)" > "$STUB_D/prd_terraform/CF_API_TOKEN"
  : > "$STUB_LOG"; run --stage verify
  [[ "$RC" -eq 1 ]] && grep -qx 'SOLEUR_CFAM_VERIFY verdict=fail' <<<"$OUT" \
    && grep -qxF 'SOLEUR_CFAM_VERIFY check=prd_terraform/CF_API_TOKEN=swapped-prev-revoked verdict=fail' <<<"$OUT" \
    && grep -qxF 'SOLEUR_CFAM_VERIFY check=prd_terraform/CF_API_TOKEN_RULESETS=swapped verdict=ok' <<<"$OUT" \
    && grep -qxF "$(printf 'read\tcurl https://api.cloudflare.com/client/v4/zones/%s' "$NZ")" "$STUB_LOG" \
    && [[ "$(mut)" -eq 0 ]]
}
# P11c: the four 0b keys were never swapped and their _NEXT deleted by hand (no _NEXT, no _PREV):
# each still holds its old, active token, and verify fails every one of them.
row_p11c_0b_never_swapped_fails() { # <bootstrap-src>
  local s k
  world p11c "$1"
  for s in prev-0a flip-ids swap-0a branch-copies-zone-id; do approve "$s"; [[ "$RC" -eq 0 ]] || return 1; done
  for k in "${K0B[@]}"; do rm -f "$STUB_D/prd_terraform/${k}_NEXT"; done
  run --stage verify
  [[ "$RC" -eq 1 ]] && grep -qx 'SOLEUR_CFAM_VERIFY verdict=fail' <<<"$OUT" || return 1
  for k in "${K0B[@]}"; do
    grep -qxF "SOLEUR_CFAM_VERIFY check=prd_terraform/${k}=swapped-prev-revoked verdict=fail" <<<"$OUT" || return 1
  done
}
# P13: an id STORED with a trailing newline (`hex\n`; the CLI prints `hex\n\n`) is not an id: id_of
# refuses it, so prev-0a will not keep it as the legacy zone id.
row_p13_id_trailing_newline_refuses() { # <bootstrap-src>
  world p13 "$1"
  printf '%s\n' "$OZ" > "$STUB_D/prd_terraform/CF_ZONE_ID"
  : > "$STUB_LOG"; run --stage prev-0a
  [[ "$RC" -eq 1 && -z "$(digest)" && "$(mut)" -eq 0 ]] && grep -qF 'SOLEUR_BOOTSTRAP_PRECONDITION_FAILED stage=prev-0a need=inventory' <<<"$OUT" \
    && grep -qF 'CF_ZONE_ID in prd_terraform no longer holds the legacy id' <<<"$OUT"
}
# P14: after the revoke recipe deleted a 0b _PREV (and its _NEXT is long gone), a re-run of
# branch-copies-tokens says the revert copy was revoked, never "run prev-0b" (which would refuse).
row_p14_revoked_prev_named() { # <bootstrap-src>
  world p14 "$1"
  full_sequence || return 1
  rm -f "$STUB_D/prd_terraform/CF_API_TOKEN_PURGE_PREV"
  : > "$STUB_LOG"; run --stage branch-copies-tokens
  [[ "$RC" -eq 1 && -z "$(digest)" && "$(mut)" -eq 0 ]] && grep -qxF 'SOLEUR_BOOTSTRAP_PRECONDITION_FAILED stage=branch-copies-tokens need=verify' <<<"$OUT" \
    && grep -qF 'prd_terraform/CF_API_TOKEN_PURGE_PREV and prd_terraform/CF_API_TOKEN_PURGE_NEXT are both absent: the revert copy was revoked' <<<"$OUT" \
    && grep -qF '(runbook Halt)' <<<"$OUT" \
    && ! grep -qF 'Run prev-0b and swap-0b first' <<<"$OUT"
}

echo "== --list =="
world list
run --list
[[ "$RC" -eq 0 && "$(grep -c '^SOLEUR_BOOTSTRAP_STAGE_DECL ' <<<"$OUT")" -eq 9 ]] \
  && grep -qx 'SOLEUR_BOOTSTRAP_STAGE_DECL stage=inventory class=read' <<<"$OUT" \
  && grep -qx 'SOLEUR_BOOTSTRAP_STAGE_DECL stage=branch-copies-tokens class=write' <<<"$OUT" \
  && grep -qx 'SOLEUR_BOOTSTRAP_STAGE_DECL stage=verify class=read' <<<"$OUT" \
  && [[ "$(grep -c . "$STUB_LOG")" -eq 0 ]]
check "--list: nine stages (inventory and verify read, the rest write), no vendor call" $?

echo "== P5: plans write nothing; no receipt, no write =="
world plans
for st in prev-0a flip-ids swap-0a branch-copies-zone-id prev-0b swap-0b branch-copies-tokens; do
  : > "$STUB_LOG"
  run --stage "$st"
  [[ "$(mut)" -eq 0 ]] && { [[ -n "$(digest)" ]] || grep -qF "SOLEUR_BOOTSTRAP_PRECONDITION_FAILED stage=${st}" <<<"$OUT"; }
  check "plan of ${st}: a plan or a named precondition, zero mutating calls" $?
done
run --stage prev-0a
d="$(digest)"; : > "$STUB_LOG"
run --stage prev-0a --apply --plan-digest "$d"
[[ "$RC" -eq 75 && "$(mut)" -eq 0 ]] && grep -qF 'SOLEUR_BOOTSTRAP_APPROVAL_REQUIRED stage=prev-0a' <<<"$OUT"
check "prev-0a --apply with no receipt: exit 75 APPROVAL_REQUIRED, nothing written" $?
run --stage flip-ids
[[ "$RC" -eq 1 && "$(mut)" -eq 0 ]] && grep -qF 'SOLEUR_BOOTSTRAP_PRECONDITION_FAILED stage=flip-ids need=prev-0a' <<<"$OUT"
check "flip-ids before prev-0a: PRECONDITION_FAILED need=prev-0a" $?
run --stage swap-0a
grep -qF 'SOLEUR_BOOTSTRAP_PRECONDITION_FAILED stage=swap-0a need=flip-ids' <<<"$OUT"
check "swap-0a before the flip: PRECONDITION_FAILED need=flip-ids" $?

echo "== P1: the whole sequence =="
world seq
run --stage inventory
[[ "$RC" -eq 0 ]] && grep -qx 'SOLEUR_CFAM_HOLDER config=prd name=CF_API_TOKEN_PURGE' <<<"$OUT" \
  && grep -qx 'SOLEUR_CFAM_STAGED config=prd_terraform name=CF_API_TOKEN_RULESETS_NEXT' <<<"$OUT" \
  && ! grep -q 'config=prd_other' <<<"$OUT"
check "inventory: names holders and staged keys by name, nothing for a config with no watched key" $?
approve prev-0a
[[ "$RC" -eq 0 && "$(val prd_terraform CF_ZONE_ID_PREV)" == "$OZ" && "$(val prd_terraform CF_API_TOKEN_PAGES_PREV)" == "$(old_val CF_API_TOKEN_PAGES)" ]] \
  && grep -qF 'SOLEUR_BOOTSTRAP_STAGE_OK stage=prev-0a changed=1 approval=harness-receipt' <<<"$OUT"
check "prev-0a: revert copies of both ids and the three 0a tokens, through a harness receipt" $?
approve flip-ids
[[ "$RC" -eq 0 && "$(val prd_terraform CF_ZONE_ID)" == "$NZ" && "$(val prd_terraform CF_ACCOUNT_ID)" == "$NA" && "$(val prd_terraform CF_R2_ACCOUNT_ID)" == "$OA" ]]
check "flip-ids: zone and account flipped, CF_R2_ACCOUNT_ID untouched" $?
run --stage prev-0a
[[ "$RC" -eq 0 && "$(ops)" == "0" ]]
check "prev-0a after the flip: satisfied (an existing revert copy is never overwritten)" $?
: > "$STUB_LOG"
approve swap-0a
[[ "$RC" -eq 0 ]] && grep -qE '^read[[:space:]]scope --profile redirects-dns --staged$' "$STUB_LOG" \
  && [[ "$(val prd_terraform CF_API_TOKEN_RULESETS)" == "$(new_val CF_API_TOKEN_RULESETS)" ]] \
  && ! has prd_terraform CF_API_TOKEN_NEXT && ! has prd_terraform CF_API_TOKEN_RULESETS_NEXT && ! has prd_terraform CF_API_TOKEN_PAGES_NEXT
check "swap-0a: staged probe ran, live keys hold the new tokens, staging keys deleted" $?
s_idx="$(grep -nE '^read[[:space:]]scope ' "$STUB_LOG" | head -1 | cut -d: -f1)"; w_idx="$(grep -nE '^mutating' "$STUB_LOG" | head -1 | cut -d: -f1)"
[[ -n "$s_idx" && -n "$w_idx" && "$s_idx" -lt "$w_idx" ]]
check "swap-0a: the scope probe ran before the first write" $?
approve branch-copies-zone-id
[[ "$RC" -eq 0 && "$(val prd CF_ZONE_ID)" == "$NZ" && "$(val prd_cla CF_ZONE_ID)" == "$NZ" && "$(val dev CF_ZONE_ID)" == "$NZ" ]] && ! has prd_other CF_ZONE_ID
check "branch-copies-zone-id: every holder gets the new id, a non-holder gets nothing" $?
: > "$STUB_LOG"
run --stage branch-copies-tokens
[[ "$RC" -eq 1 && "$(mut)" -eq 0 && -z "$(digest)" ]] && grep -qF 'SOLEUR_BOOTSTRAP_PRECONDITION_FAILED stage=branch-copies-tokens need=swap-0b' <<<"$OUT" \
  && [[ "$(val prd CF_API_TOKEN_PURGE)" == "$(old_val CF_API_TOKEN_PURGE)" ]]
check "P2a branch-copies-tokens before swap-0b: PRECONDITION_FAILED need=swap-0b, prd keeps its value" $?
approve prev-0b; check "prev-0b applies" "$RC"
: > "$STUB_LOG"
approve swap-0b
[[ "$RC" -eq 0 ]] && grep -qE '^read[[:space:]]scope --profile zone-rest --staged$' "$STUB_LOG" \
  && [[ "$(grep -c 'curl https://api.cloudflare.com/client/v4/user/tokens/verify' "$STUB_LOG")" -eq 2 ]] \
  && [[ "$(val prd_terraform CF_API_TOKEN_PURGE)" == "$(new_val CF_API_TOKEN_PURGE)" ]] && ! has prd_terraform CF_API_TOKEN_DNS_EDIT_NEXT
check "swap-0b: zone-rest probe plus two active checks (DNS_EDIT, PURGE), then the swap" $?
approve branch-copies-tokens
[[ "$RC" -eq 0 && "$(val prd CF_API_TOKEN_PURGE)" == "$(new_val CF_API_TOKEN_PURGE)" && "$(val prd CF_API_TOKEN_DNS_EDIT)" == "$(new_val CF_API_TOKEN_DNS_EDIT)" ]] && ! has prd_cla CF_API_TOKEN_PURGE
check "branch-copies-tokens: prd takes the new PURGE and DNS_EDIT from prd_terraform; non-holders untouched" $?
run --stage verify
[[ "$RC" -eq 0 ]] && grep -qx 'SOLEUR_CFAM_VERIFY verdict=ok' <<<"$OUT" && ! grep -q 'verdict=fail' <<<"$OUT"
check "verify: every check ok" $?
allzero=0
for st in prev-0a flip-ids swap-0a branch-copies-zone-id prev-0b swap-0b branch-copies-tokens; do
  : > "$STUB_LOG"; run --stage "$st"
  [[ "$RC" -eq 0 && "$(ops)" == "0" && "$(mut)" -eq 0 ]] || { allzero=1; echo "    not satisfied: $st ($(ops))"; }
done
check "every write stage is satisfied afterwards (operations=0, no write)" "$allzero"
printf '%s' "$OA" > "$STUB_D/prd_terraform/CF_ZONE_ID"
run --stage verify
[[ "$RC" -eq 1 ]] && grep -qx 'SOLEUR_CFAM_VERIFY check=prd_terraform/CF_ZONE_ID=new verdict=fail' <<<"$OUT"
check "verify goes red (STAGE_FAILED) when a checked value regresses" $?

echo "== flip-ids guard (D8 parity) =="
world r2
approve prev-0a
printf '%s' "$NA" > "$STUB_D/prd_terraform/CF_R2_ACCOUNT_ID"
run --stage flip-ids
[[ "$RC" -eq 1 && -z "$(digest)" ]] && grep -qF 'SOLEUR_BOOTSTRAP_PRECONDITION_FAILED stage=flip-ids need=inventory' <<<"$OUT"
check "flip-ids refuses while CF_R2_ACCOUNT_ID holds the new account id" $?

echo "== unreadable is inconclusive, never absent =="
world unread
approve prev-0a; approve flip-ids
: > "$STUB_D/.unreadable/prd_cla"
run --stage branch-copies-zone-id
[[ "$RC" -eq 1 && -z "$(digest)" ]] && grep -qF 'SOLEUR_BOOTSTRAP_PRECONDITION_FAILED stage=branch-copies-zone-id need=inventory' <<<"$OUT"
check "branch-copies-zone-id refuses when one config's names listing is unreadable" $?

echo "== P2b / P3 / P4 on the real script =="
row_p2b_restaged_refuses "$SCRIPT_SRC"; check "P2b branch-copies-tokens refuses while a fresh _NEXT is staged after swap-0b" $?
row_p3_mismatch_keeps_next "$SCRIPT_SRC"; check "P3 a copy that does not read back equal stops before any delete (every _NEXT kept); after its rollback the re-run swaps" $?
row_p3b_drift_keeps_next "$SCRIPT_SRC"; check "P3b a key that moved after its copy keeps <KEY>_NEXT (compare above the delete)" $?
row_p4_probe_fail_stops "$SCRIPT_SRC"; check "P4 a failed scope probe stops swap-0a before any write" $?
row_p6_bad_revert_copy_refuses "$SCRIPT_SRC"; check "P6 a revert copy that does not hold the old token satisfies neither prev-0a nor swap-0a" $?
row_p7_empty_revert_copy_refuses "$SCRIPT_SRC"; check "P7 an empty revert copy satisfies neither prev-0a nor swap-0a" $?
row_p8_third_zone_refuses "$SCRIPT_SRC"; check "P8 branch-copies-zone-id refuses a CF_ZONE_ID that is neither the legacy nor the new id" $?
row_p6m_garbage_key_neutral "$SCRIPT_SRC"; check "P6m garbage <KEY> with a good _PREV: prev and swap re-runs give the neutral copy-neither-way refusal" $?
row_p9_cli_newline "$SCRIPT_SRC"; check "P9 under the real-CLI newline, copies are byte-exact and staged tokens read active" $?
row_p10_malformed_next "$SCRIPT_SRC" quote; check "P10 a staged token with a quote: TOKEN_MALFORMED, no curl call, no write" $?
row_p10_malformed_next "$SCRIPT_SRC" newline; check "P10 a staged token with an embedded newline: TOKEN_MALFORMED, no curl call, no write" $?
row_p11_verify_prev_revoked "$SCRIPT_SRC" ok; check "P11 verify after the 0a _PREV revoke: ok via swapped-prev-revoked" $?
row_p11_verify_prev_revoked "$SCRIPT_SRC" inactive; check "P11 verify with _PREV revoked and the live key inactive: fail" $?
row_p12a_branch_third_token_refuses "$SCRIPT_SRC"; check "P12a branch-copies-tokens refuses a branch token that is neither the new nor the old one" $?
row_p12b_crossed_legacy_id_refuses "$SCRIPT_SRC"; check "P12b prev-0a refuses CF_ZONE_ID holding the legacy account id" $?
row_p12c_bad_id_prev_refuses "$SCRIPT_SRC"; check "P12c prev-0a refuses a CF_ZONE_ID_PREV that is not the legacy zone id" $?
row_p11b_old_token_no_prev_fails "$SCRIPT_SRC"; check "P11b verify fails a key holding the old (still active) token with no _PREV and no _NEXT" $?
row_p11c_0b_never_swapped_fails "$SCRIPT_SRC"; check "P11c verify fails every never-swapped 0b key once its _NEXT is gone and no _PREV exists" $?
row_p13_id_trailing_newline_refuses "$SCRIPT_SRC"; check "P13 an id stored as hex plus newline is refused by id_of (prev-0a will not keep it)" $?
row_p14_revoked_prev_named "$SCRIPT_SRC"; check "P14 branch-copies-tokens after a revoked 0b _PREV names the revoke, not prev-0b" $?

echo "== P5: no synthesized secret value in any output =="
! grep -qE 'SYNTH-(OLD|NEW)[^ ]*SENTINEL' "$ALL_OUT"
check "no SYNTH-*-SENTINEL value appears in any stdout/stderr" $?

echo "== mutations =="
mutate() { # <label> <dst> — perl program on stdin; proves it landed
  local label="$1" dst="$2" prog; prog="$(cat)"
  assert_fixture_dir "$dst"
  cp "$SCRIPT_SRC" "$dst"; perl -0777 -pi -e "$prog" "$dst"
  if cmp -s "$dst" "$SCRIPT_SRC"; then fail "mutation ${label} did not land"; return 1; fi
  bash -n "$dst" 2>/dev/null || { fail "mutation ${label} does not parse"; return 1; }
  pass "mutation ${label} landed (differs from the source, bash -n clean)"
}
if mutate M1 "$SB/m1.sh" <<'PERL'; then
s{(  for k in \$\{COPY_KEYS\[\@\]\+"\$\{COPY_KEYS\[\@\]\}"\} \$\{DEL_KEYS\[\@\]\+"\$\{DEL_KEYS\[\@\]\}"\}; do\n)}{$1    doppler secrets delete "\$\{k\}_NEXT" -p "\$PROJ" -c "\$TFC" --yes >/dev/null 2>&1 || true\n}
PERL
  row_p3b_drift_keeps_next "$SB/m1.sh"; r=$?
  [[ "$r" -ne 0 ]]; check "M1 (delete above the compare) turns P3b RED" $?
fi
if mutate M2 "$SB/m2.sh" <<'PERL'; then
s{    in_names "\$\{k\}_NEXT" "\$TF_NAMES" \\\n      && soleur_op_precondition_failed branch-copies-tokens swap-0b [^\n]*\n}{}
PERL
  row_p2b_restaged_refuses "$SB/m2.sh"; r=$?
  [[ "$r" -ne 0 ]]; check "M2 (the _NEXT refusal dropped) turns P2b RED" $?
fi
if mutate M3 "$SB/m3.sh" <<'PERL'; then
s{    run_scope_probe "\$profile" \|\| return 1\n}{}
PERL
  row_p4_probe_fail_stops "$SB/m3.sh"; r=$?
  [[ "$r" -ne 0 ]]; check "M3 (the scope probe dropped) turns P4 RED" $?
fi
if mutate M4 "$SB/m4.sh" <<'PERL'; then
s{      prev_copy_sound "\$stage" "\$k"; continue\n}{      continue\n}
PERL
  row_p6_bad_revert_copy_refuses "$SB/m4.sh"; r=$?
  [[ "$r" -ne 0 ]]; check "M4 (an existing _PREV accepted by name) turns P6 RED" $?
  row_p7_empty_revert_copy_refuses "$SB/m4.sh"; r=$?
  [[ "$r" -ne 0 ]]; check "M4 (an existing _PREV accepted by name) turns P7 RED" $?
fi
if mutate M5 "$SB/m5.sh" <<'PERL'; then
s{        \[\[ "\$dk" == "\$dp" \]\] \\\n          \|\| soleur_op_precondition_failed [^\n]*\n}{}
PERL
  row_p6_bad_revert_copy_refuses "$SB/m5.sh"; r=$?
  [[ "$r" -ne 0 ]]; check "M5 (swap overwrites a key that no longer holds its revert copy) turns P6 RED" $?
fi
if mutate M6 "$SB/m6.sh" <<'PERL'; then
s{    dp="\$\(digest_of "\$TFC" "\$\{k\}_PREV"\)" \|\| soleur_op_precondition_failed "\$stage" "\$prev" [^\n]*\n}{    dp="\$(digest_of "\$TFC" "\$\{k\}_PREV" || true)"\n}
PERL
  row_p7_empty_revert_copy_refuses "$SB/m6.sh"; r=$?
  [[ "$r" -ne 0 ]]; check "M6 (swap tolerates an unreadable _PREV) turns P7 RED" $?
fi
if mutate M7 "$SB/m7.sh" <<'PERL'; then
s{    \[\[ "\$v" == "\$OLD_ZONE" \]\] \\\n      \|\| soleur_op_precondition_failed branch-copies-zone-id [^\n]*\n}{}
PERL
  row_p8_third_zone_refuses "$SB/m7.sh"; r=$?
  [[ "$r" -ne 0 ]]; check "M7 (branch copy overwrites any zone id) turns P8 RED" $?
fi
if mutate M0 "$SB/m0.sh" <<'PERL'; then
s{ \| LC_ALL=C awk '[^'\n]*'\n}{\n}
PERL
  row_p9_cli_newline "$SB/m0.sh"; r=$?
  [[ "$r" -ne 0 ]]; check "M0 (the CLI's trailing newline kept, the pre-fix reads) turns P9 RED" $?
  row_p7_empty_revert_copy_refuses "$SB/m0.sh"; r=$?
  [[ "$r" -ne 0 ]]; check "M0 (the CLI's trailing newline kept) turns P7 RED (an empty value no longer reads empty)" $?
fi
if mutate M8 "$SB/m8.sh" <<'PERL'; then
s{  \[\[ "\$fail" -eq 0 \]\] \|\| return 1\n}{}
PERL
  row_p3_mismatch_keeps_next "$SB/m8.sh"; r=$?
  [[ "$r" -ne 0 ]]; check "M8 (deletes run after a failed copy) turns P3 RED" $?
fi
if mutate M9 "$SB/m9.sh" <<'PERL'; then
s{  bad="\$\(set -o pipefail; plain_get [^\n]*\n  \[\[ "\$bad" -eq 0 \]\] [^\n]*\n}{}
PERL
  row_p10_malformed_next "$SB/m9.sh" quote; r=$?
  [[ "$r" -ne 0 ]]; check "M9 (token_active's character check dropped) turns P10 quote RED" $?
  row_p10_malformed_next "$SB/m9.sh" newline; r=$?
  [[ "$r" -ne 0 ]]; check "M9 (token_active's character check dropped) turns P10 newline RED" $?
fi
if mutate M10 "$SB/m10.sh" <<'PERL'; then
s{ && token_active "\$TFC" "\$k" && token_reads_new_zone }{ && token_reads_new_zone }
PERL
  row_p11_verify_prev_revoked "$SB/m10.sh" inactive; r=$?
  [[ "$r" -ne 0 ]]; check "M10 (verify skips the active check on a revoked _PREV) turns P11 negative RED" $?
fi
if mutate M11 "$SB/m11.sh" <<'PERL'; then
s{      \[\[ -n "\$dc" && "\$dc" == "\$old" \]\] \\\n        \|\| soleur_op_precondition_failed [^\n]*\n}{}
PERL
  row_p12a_branch_third_token_refuses "$SB/m11.sh"; r=$?
  [[ "$r" -ne 0 ]]; check "M11 (branch copy overwrites any token) turns P12a RED" $?
fi
if mutate M12 "$SB/m12.sh" <<'PERL'; then
s{        \[\[ "\$v" == "\$want" \]\] \\\n}{        [[ "\$v" == "\$OLD_ZONE" || "\$v" == "\$OLD_ACCT" ]] \\\n}
PERL
  row_p12b_crossed_legacy_id_refuses "$SB/m12.sh"; r=$?
  [[ "$r" -ne 0 ]]; check "M12 (either legacy id accepted for either key) turns P12b RED" $?
fi
if mutate M13 "$SB/m13.sh" <<'PERL'; then
s{      \[\[ "\$\(id_of "\$TFC" "\$\{k\}_PREV" \|\| true\)" == "\$want" \]\] \\\n}{      true \\\n}
PERL
  row_p12c_bad_id_prev_refuses "$SB/m13.sh"; r=$?
  [[ "$r" -ne 0 ]]; check "M13 (an id-key _PREV accepted without its value) turns P12c RED" $?
fi
if mutate M14 "$SB/m14.sh" <<'PERL'; then
s{ && token_reads_new_zone "\$TFC" "\$k" && r=0\n}{ && r=0\n}
PERL
  row_p11b_old_token_no_prev_fails "$SB/m14.sh"; r=$?
  [[ "$r" -ne 0 ]]; check "M14 (verify's new-zone read dropped) turns P11b RED" $?
  row_p11c_0b_never_swapped_fails "$SB/m14.sh"; r=$?
  [[ "$r" -ne 0 ]]; check "M14 (verify's new-zone read dropped) turns P11c RED" $?
fi
if mutate M15 "$SB/m15.sh" <<'PERL'; then
s{  v="\$\(plain_get "\$1" "\$2" && printf x\)" \|\| return 1\n  v="\$\{v%x\}"\n}{  v="\$(doppler secrets get "\$2" -p "\$PROJ" -c "\$1" --plain 2>/dev/null)" || return 1\n}
PERL
  row_p13_id_trailing_newline_refuses "$SB/m15.sh"; r=$?
  [[ "$r" -ne 0 ]]; check "M15 (id_of back on a newline-stripping capture) turns P13 RED" $?
fi
if mutate M16 "$SB/m16.sh" <<'PERL'; then
s{ \|\| \{ fail=1; break; \}\n}{ || fail=1\n}
PERL
  row_p3_mismatch_keeps_next "$SB/m16.sh"; r=$?
  [[ "$r" -ne 0 ]]; check "M16 (the copy loop runs on after a failed copy) turns P3 RED" $?
fi

# --- anti-vacuity floor (reported directly, never through fail()) ---------------
TOTAL=$((PASS + FAIL))
FLOOR=86
if [[ "$TOTAL" -lt "$FLOOR" ]]; then
  printf '  [FAIL] anti-vacuity floor: only %s assertions ran, floor is %s\n' "$TOTAL" "$FLOOR" >&2
  printf 'Total: %s assertions, %s failed\n' "$TOTAL" "$((FAIL + 1))"
  exit 1
fi
echo "Total: ${TOTAL} assertions, ${FAIL} failed"
[[ "$FAIL" -eq 0 ]]
